-- Cineo 0.7: account boundaries, media jobs and editorial tools. Existing media remains untouched.
alter table public.cineo_shows add column allow_download boolean not null default false;
alter table public.cineo_shows add column credits jsonb not null default '[]';
alter table public.cineo_shows add column featured_order integer;
alter table public.cineo_profiles add column verified boolean not null default false;
alter table public.cineo_episodes add column release_at timestamptz;
alter table public.cineo_episodes add column intro_start integer not null default 0;
alter table public.cineo_episodes add column intro_end integer not null default 0;
alter table public.cineo_episodes add column credits_start integer not null default 0;
alter table public.cineo_episodes add column audio_tracks jsonb not null default '[]';
alter table public.cineo_episodes add column medium_path text not null default '';
alter table public.cineo_episodes add column thumb_path text not null default '';
alter table public.cineo_episodes add column media_state text not null default 'legacy' check(media_state in ('legacy','queued','processing','ready','failed'));
create table public.cineo_viewers(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 40),kids boolean not null default false,max_rating integer not null default 18 check(max_rating in (0,10,12,14,16,18)),created_at timestamptz not null default now());
create index cineo_viewers_owner on public.cineo_viewers(user_id);
create table public.cineo_parental(user_id uuid primary key references auth.users(id) on delete cascade,salt text not null,pin_hash text not null);
create table public.cineo_viewer_progress(viewer_id uuid not null references public.cineo_viewers(id) on delete cascade,episode_id bigint not null references public.cineo_episodes(id) on delete cascade,position_ms integer not null check(position_ms>=0),duration_ms integer not null check(duration_ms between 1 and 14400000),completed boolean not null default false,updated_at timestamptz not null default now(),primary key(viewer_id,episode_id));
create index cineo_viewer_progress_episode on public.cineo_viewer_progress(episode_id);
create table public.cineo_viewer_saved(viewer_id uuid not null references public.cineo_viewers(id) on delete cascade,show_id bigint not null references public.cineo_shows(id) on delete cascade,created_at timestamptz not null default now(),primary key(viewer_id,show_id));
create index cineo_viewer_saved_show on public.cineo_viewer_saved(show_id);
create table public.cineo_devices(session_id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,name text not null default 'Android',last_seen timestamptz not null default now(),revoked boolean not null default false);
create index cineo_devices_owner on public.cineo_devices(user_id);
create table public.cineo_notification_prefs(user_id uuid primary key references auth.users(id) on delete cascade,episodes boolean not null default true,corrections boolean not null default true,start_hour integer not null default 8 check(start_hour between 0 and 23),end_hour integer not null default 22 check(end_hour between 0 and 23));
create table public.cineo_bulletins(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,show_id bigint not null references public.cineo_shows(id) on delete cascade,title text not null check(length(title) between 1 and 200),created_at timestamptz not null default now());
create index cineo_bulletins_owner on public.cineo_bulletins(user_id,id);
create index cineo_bulletins_show on public.cineo_bulletins(show_id);
create table public.cineo_collaborators(show_id bigint not null references public.cineo_shows(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('viewer','editor')),primary key(show_id,user_id));
create index cineo_collaborators_user on public.cineo_collaborators(user_id);
create table public.cineo_appeals(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,show_id bigint not null references public.cineo_shows(id) on delete cascade,message text not null check(length(message) between 10 and 2000),status text not null default 'open' check(status in ('open','answered')),reply text not null default '',created_at timestamptz not null default now());
create index cineo_appeals_owner on public.cineo_appeals(user_id);
create index cineo_appeals_show on public.cineo_appeals(show_id);
create table public.cineo_media_jobs(id uuid primary key default gen_random_uuid(),episode_id bigint not null unique references public.cineo_episodes(id) on delete cascade,status text not null default 'queued' check(status in ('queued','processing','ready','failed')),lease uuid,attempts integer not null default 0,message text not null default '',details jsonb not null default '{}',updated_at timestamptz not null default now());
create index cineo_media_jobs_queue on public.cineo_media_jobs(status,updated_at);
create table public.cineo_uploads(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,show_id bigint not null references public.cineo_shows(id) on delete cascade,title text not null check(length(title) between 1 and 100),season integer not null check(season between 1 and 1000),chapter integer not null check(chapter between 1 and 10000),total integer not null check(total between 12 and 26214400),seconds integer not null default 0 check(seconds between 0 and 14400),episode_id bigint references public.cineo_episodes(id) on delete set null,created_at timestamptz not null default now());
create index cineo_uploads_owner on public.cineo_uploads(user_id);
create index cineo_uploads_show on public.cineo_uploads(show_id);
create index cineo_uploads_episode on public.cineo_uploads(episode_id);
create table public.cineo_upload_parts(upload_id uuid not null references public.cineo_uploads(id) on delete cascade,part integer not null check(part between 0 and 12),bytes integer not null check(bytes between 1 and 2097152),primary key(upload_id,part));
create table public.cineo_faults(id bigint generated always as identity primary key,user_id uuid references auth.users(id) on delete set null,kind text not null check(length(kind) between 1 and 40),code text not null check(length(code)<=100),created_at timestamptz not null default now());
create index cineo_faults_owner on public.cineo_faults(user_id);
create table public.cineo_retention(user_id uuid not null references auth.users(id) on delete cascade,episode_id bigint not null references public.cineo_episodes(id) on delete cascade,day date not null default current_date,bucket integer not null check(bucket between 0 and 9),primary key(user_id,episode_id,day,bucket));
create index cineo_retention_episode on public.cineo_retention(episode_id);
create table public.cineo_erasure(user_id uuid primary key references auth.users(id) on delete cascade,requested_at timestamptz not null default now(),execute_after timestamptz not null default now()+interval '7 days');
do $$ declare t text;begin foreach t in array array['cineo_viewers','cineo_parental','cineo_viewer_progress','cineo_viewer_saved','cineo_devices','cineo_notification_prefs','cineo_bulletins','cineo_collaborators','cineo_appeals','cineo_media_jobs','cineo_uploads','cineo_upload_parts','cineo_faults','cineo_retention','cineo_erasure'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant usage,select on all sequences in schema public to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('cineo-chunks','cineo-chunks',false,2097152,array['application/octet-stream']) on conflict(id) do nothing;
create function public.cineo_claim_media() returns setof public.cineo_media_jobs language plpgsql security invoker set search_path='' as $$
declare job public.cineo_media_jobs;begin
 select * into job from public.cineo_media_jobs where status='queued' or (status='processing' and updated_at<now()-interval '30 minutes') order by updated_at for update skip locked limit 1;
 if not found then return;end if;
 update public.cineo_media_jobs set status='processing',lease=gen_random_uuid(),attempts=attempts+1,updated_at=now() where id=job.id returning * into job;
 update public.cineo_episodes set media_state='processing' where id=job.episode_id;return next job;end $$;
revoke all on function public.cineo_claim_media() from public,anon,authenticated;grant execute on function public.cineo_claim_media() to service_role;
create function public.cineo_schedule_media() returns trigger language plpgsql security invoker set search_path='' as $$begin insert into public.cineo_media_jobs(episode_id) values(new.id) on conflict(episode_id) do update set status='queued',updated_at=now();new.media_state='queued';return new;end $$;
-- AFTER trigger queues jobs; queued state is set by API so legacy rows stay playable.
create trigger cineo_media_job_insert after insert on public.cineo_episodes for each row execute function public.cineo_schedule_media();
revoke all on function public.cineo_schedule_media() from public,anon,authenticated;grant execute on function public.cineo_schedule_media() to service_role;
create function public.cineo_weekly_top() returns table(id bigint,views bigint) language sql stable security invoker set search_path='' as $$select e.show_id,count(distinct p.user_id) from public.cineo_progress p join public.cineo_episodes e on e.id=p.episode_id where p.updated_at>now()-interval '7 days' and p.position_ms>=1000 group by e.show_id order by 2 desc limit 10$$;
revoke all on function public.cineo_weekly_top() from public,anon,authenticated;grant execute on function public.cineo_weekly_top() to service_role;
